def money(x: Decimal) -> Decimal:
    return x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
def pct(x: Decimal) -> str:
    return f"{(x *Decimal('100')).quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP)}%"



def getPoints(collectionName, tenant_id):
    vector_resp = vector()

    resp = qdrant.query_points(
        collection_name=collectionName,
        query=vector_resp,
        limit=10,
        using='dense_vector',
        with_payload=True,
        
        query_filter=Filter(
            must=[
                FieldCondition(
                    key="tenantid",
                    match=MatchValue(value=tenant_id)
                )
            ]
        )
    )
    results = resp.points
    context = "\n\n".join([
     f"source_doc = {r.payload.get('source_doc', 'unknown')}, pageNumber = {r.payload.get('pageNumber', 'N/A')})\n{r.payload['text']}"
        for r in results if "text" in r.payload
        ])
    return context

def runCPICalculation(tenant_id, collectionName="Lease_Link", claude_model="claude-sonnet-4-20250514"):
    context = getPoints(collectionName, tenant_id)
    now = datetime.now()

    system_prompt = f"""You are a leasing analyst. You're goal is to give us the variables to calculate CPI based rent adjustments for a commercial lease. We do not need explanations, just the process.
    Use this context from the lease to find the necessary information: {context}
    Current Time: {now}
    We need the following information in json format:
    json
    RULES:
    For Kind Options:
    - "Year-Over-Year"
    - "Rolling-Base"
    - "Average"
    - "Triennial-Cumulative"
    - "Fixed-Percentage"
    - "Look-Back"
    - "Reset-Base"
    - "Spread"
First Year
Return the earliest calendar year whose Index value in the Comparison Month is needed to compute the rent adjustment.

End Year
Determine the Adjustment Years from the lease frequency (e.g., every 3rd Lease Year / every N years) starting from the first adjustment date.

Identify the latest Adjustment Year whose effective date is on or before today.

If the next scheduled adjustment is in the future, use the previous adjustment.

Return the Index observation year used for that adjustment:

Return the latest calendar year whose Index value in the Comparison Month is required to compute that adjustment.

In some leases, this is the calendar year immediately preceding the effective Adjustment Year (because the Comparison Month is in the prior year).

Do not return a future year.
Do not return the first adjustment unless it is the most recent completed adjustment (rare).
Make sure to calculate what it would be for the most recent rent frequency (If today is 2026), not the end of the lease

Rules

Use the lease-defined Comparison Month (not always December).

If the lease says “Comparison Month is X, or if not published then the immediately preceding month,” still use the Comparison Month year (same calendar year) — the fallback month does not change the year unless the Comparison Month is January and you fall back into December of the prior year (rare, but handle it).

The years returned must refer to the Index observation years, not the Adjustment Year itself.
    """ + """
{
    'index_series" {
        'name': string, # Name of the index series (e.g., "Consumer Price Index for All Urban Consumers: All Items in U.S. City Average"),
        'series_id: string # Series ID used to look up CPI data (e.g., "CUUR0000SA0"),
        'index_substitution': Fall Back Series ID
    },
    'comparison_month': The month that we are comparing for CPI in M01 format (M13 for yearly forcast)
    'fallback_if_unpublished': string # What to do if the CPI data is not published for the comparison month (e.g., "use last available month", "use average of last 3 months", etc.)
    'adjustment_dates_rule': {
    'kind': 'calendar_date',
    'month': int, # Month of the year when adjustment occurs (1-12),
    'day': int # Day of the month when adjustment occurs (1-31),
    'first_year': int # Return the earliest calendar year whose Index value in the Comparison Month is needed to compute the rent adjustment.

    'end_year': Follow End Year Instructions above
    'frequency_years': int # Frequency of adjustment in years (e.g., 1 for annual, 3 for every 3 years, etc.),
    },
    'adjustment_factor_rule': {
    "kind": 'Average',(Follow Kind Rules)
    "years_lookback": 3,
    "yoy_measruement": "same_month or MX(1-13)": Determine what the final CPI calculation month for the period is
    },
    "base_rent": {
        "annual": Decimal # Base annual rent amount (e.g., 120000.00),
        "monthly": Decimal # Base monthly rent amount (e.g., 10000.00),
        "currency": "USD" # Currency of the rent amounts,
        },
    "rounding": {
    "money_decimals": int # Number of decimal places to round monetary amounts (e.g., 2 for cents),
    "percent_decimals": int # Number of decimal places to round percentage amounts (e.g., 6 for micro-percentage),
    },
    'assumptions': string # Any assumptions made during the extraction,
    'needs_human_review': boolean # Whether the extraction needs human review
}"""    
    ai_message = f"""Using the above system prompt, extract the CPI lease variables from the provided lease context."""
    chat_response = claude.messages.create(
        model=claude_model,
        system=(system_prompt),
        messages=[
            {"role": "user", 'content': [
                {
                    'type': 'text',
                    'text': ai_message
                }
            ]}
        ],
        temperature=0.0,
        max_tokens=800
    )
    token_usage = chat_response.usage
    prompt_tokens = token_usage.input_tokens
    completion_tokens = token_usage.output_tokens
    chat_message = chat_response.content[0].text
    rent = 0.0
    


    json_data = Qdrant_ChatGPT._extract_after_fence(chat_message, "json")
    print("STEP 2 Extracted JSON:", json.dumps(json_data, indent=2))
    if json_data:
        series_id = json_data['index_series']['series_id']
        comparison_period = json_data['comparison_month']
        base_rent_annual = json_data['base_rent']['annual']
        kind = json_data['adjustment_factor_rule']['kind']
        start_year = json_data['adjustment_dates_rule']['first_year']
        frequency_years = json_data['adjustment_dates_rule']['frequency_years']
        end_year = json_data['adjustment_dates_rule']['end_year']
        yoy_measurement = json_data['adjustment_factor_rule']['yoy_measurement']
        rent = CPICalculation(series_id, start_year, end_year, comparison_period, base_rent_annual, frequency_years, kind, yoy_measurement)


    return rent, prompt_tokens, completion_tokens


    

def CPICalculation(series, Start_Year, End_Year, Comparison_Period, BASE_RENT_ANNUAL, frequency_years, kind, yoy_measurement):
    payload = {
        "seriesid": [series],
        "startyear": str(Start_Year),
        "endyear": str(End_Year),
        "registrationkey": api_key
    }
    comparisons = {
        "M01": "M12",
        "M02": "M01",
        "M03": "M02",
        "M04": "M03",
        "M05": "M04",
        "M06": "M05",
        "M07": "M06",
        "M08": "M07",
        "M09": "M08",
        "M10": "M09",
        "M11": "M10",
        "M12": "M11",
        "M13": "M13"
    }
    previous_comparison = comparisons[Comparison_Period]
    print("Previous Comparison", previous_comparison)
    
    print("STEP 1 Payload (key hiddent):")
    safe_payload = dict(payload)
    safe_payload["registrationkey"] = "HIDDEN"

    resp = requests.post(BLS_ENDPOINT, json=payload, timeout=30)
    resp.raise_for_status()
    data = resp.json()
    with open ('CPIdata.txt', 'w') as f:
        f.write(json.dumps(data, indent=2))

    if data.get('status') != "REQUEST_SUCCEEDED":
        return
    series_data = data['Results']['series'][0]
    points = series_data['data']

    Comparison_Data = {}
    Final_Comparison = {}

    def fallback(period, y): 
        previous = comparisons[period]
        fallback_val = next(
                    (p["value"] for p in points
                    if int(p["year"]) == y
                    and p["period"] == previous
                    and p.get("value") not in ("-", "null", None, "")),
                    None
                )
        if fallback_val is None:
                    print(f"Missing CPI for {y} {period} and fallback {previous}")
                    return 0
        return fallback_val

    for point in points:
        if point['period'] == Comparison_Period:
            y = point['year']
            if point['value'] != '-' and point['value'] != 'null' and point['value'] != None:
                Comparison_Data[int(point['year'])] = Decimal(point['value'])
            else:
                # find fallback in same year using previous_comparison
                fallback_val = fallback(Comparison_Period, y)
                Comparison_Data[y] = Decimal(fallback_val)

        if yoy_measurement == 'same_month':
            Final_Comparison = Comparison_Data
        elif point['period'] == previous_comparison:
            if point['value'] != '-' and point['value'] != 'null' and point['value'] != None:
                Final_Comparison[int(point['year'])] = Decimal(point['value'])
            else:
                fallback_val = fallback(previous_comparison, y)
                Final_Comparison[int(point['year'])] = Decimal(fallback_val)
    
    for y in range(Start_Year , End_Year + 1):
        if y not in Comparison_Data:
            print(f"Missing data for year {y}")
            return
    current_year = Start_Year

    rent = Decimal(BASE_RENT_ANNUAL)
    while current_year + frequency_years <= End_Year:
        rent_changes = []
        print("Kind", kind)
        if kind == "Triennial-Cumulative":
            change = (Final_Comparison[End_Year] / Comparison_Data[Start_Year]) - Decimal("1")
            rent = simple_cpi(rent, change)
            break
        for y in range(current_year + 1, current_year + frequency_years + 1):
            change = yoy_change(Final_Comparison[y], Comparison_Data[y-1])
            print("Change", change)
            rent_changes.append(Decimal(change))
            if kind == "Year-Over-Year":
                rent = simple_cpi(rent, change)
                
                print(rent/12)
        if not rent_changes:
            break
        if kind == "Average":
            rent = average_CPI(rent_changes, rent)
            
            print(rent/12)
        elif kind == "Rolling-Base":

            rent = simple_cpi(rent, sum(rent_changes))
            print(rent/12)


        current_year = current_year + frequency_years


    monthly_rent = (rent / Decimal("12")).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP
        )
    return monthly_rent

def average_CPI(rent_changes, rent): 
         
    avg_change = sum(rent_changes)/Decimal(len(rent_changes))
    current_rent = rent*(Decimal("1") + avg_change)

    
    return current_rent
   



def simple_cpi(rent: Decimal, change: Decimal) -> Decimal:
    # change is something like Decimal("0.03") for +3%
    return rent * (Decimal("1") + change)

